body.script:

var BOT_ID = document.body.dataset.botId;
var REQUEST_ID = new URLSearchParams(window.location.search)
    .get("request") || "";
var tg = window.Telegram.WebApp;
tg.ready();
tg.expand();
var listEl = document.getElementById("list");
var ICON = {
    check: '<i class="fa fa-check text-success"></i>',
    times: '<i class="fa fa-times text-danger"></i>'
};
var STATE_ICON = {
    new: '<i class="fa fa-pencil-square-o"></i> ',
    pending: '<i class="fa fa-paper-plane-o"></i> ',
    approved: '<i class="fa fa-check-circle text-success"></i> ',
    refused: '<i class="fa fa-times-circle text-danger"></i> '
};
var L = {states: {}, priorities: {}};

function useLabels(labels) {
    if (!labels) { return; }
    L = labels;
    document.documentElement.lang = L.lang;
    document.title = L.title;
    document.getElementById("heading").textContent = L.title;
}

function reqState(state) {
    return L.states[state]
        ? STATE_ICON[state] + esc(L.states[state]) : "";
}
var APPR_ICON = {
    pending: '<i class="fa fa-clock-o text-muted"></i>',
    waiting: '<i class="fa fa-hourglass-half text-muted"></i>',
    approved: '<i class="fa fa-check-circle text-success"></i>',
    refused: '<i class="fa fa-times-circle text-danger"></i>',
    new: '<i class="fa fa-circle-o text-muted"></i>'
};

// Signed session issued by the server after it validates
// initData once. Sending it instead of initData is what
// keeps the bot token from being decrypted per request.
var SESSION = null;

function money(currency, amount) {
    return (currency || "") + Number(amount || 0).toLocaleString(
        L.lang, {minimumFractionDigits: 2, maximumFractionDigits: 2});
}

function kv(label, value) {
    var row = el("div", "kv");
    row.appendChild(el("span", "k", esc(label)));
    row.appendChild(el("span", "v", esc(value)));
    return row;
}

function attUrl(a) {
    var credential = SESSION
        ? "s=" + encodeURIComponent(SESSION)
        : "init_data=" + encodeURIComponent(tg.initData);
    return window.location.origin
        + "/telegram/approval/app/" + BOT_ID
        + "/attachment/" + a.id
        + "?" + credential;
}

function attIcon(a) {
    if (a.is_image) {
        return '<i class="fa fa-file-image-o text-success"></i> ';
    }
    if ((a.mimetype || "").indexOf("pdf") >= 0) {
        return '<i class="fa fa-file-pdf-o text-danger"></i> ';
    }
    return '<i class="fa fa-paperclip text-muted"></i> ';
}

function attachmentRow(a) {
    var row = el("div", "att");
    if (a.is_image) {
        var img = el("img", "att-thumb");
        img.src = attUrl(a);
        img.alt = a.name || L.attachment;
        row.appendChild(img);
    }
    row.appendChild(el("span", "att-name",
        attIcon(a) + esc(a.name || L.attachment)));
    row.onclick = function () { openPreview(a); };
    return row;
}

function openPreview(a) {
    var url = attUrl(a);
    var overlay = el("div", "overlay");
    var close = el("div", "overlay-close",
        '<i class="fa fa-times"></i>');
    function dismiss() {
        if (overlay.parentNode) {
            document.body.removeChild(overlay);
        }
    }
    close.onclick = dismiss;
    overlay.onclick = function (e) {
        if (e.target === overlay) { dismiss(); }
    };
    var viewer;
    if (a.is_image) {
        viewer = el("img", "overlay-img");
    } else {
        viewer = el("iframe", "overlay-frame");
    }
    viewer.src = url;
    overlay.appendChild(close);
    overlay.appendChild(viewer);
    document.body.appendChild(overlay);
}

function auth(params) {
    var payload = {};
    Object.keys(params).forEach(function (k) {
        payload[k] = params[k];
    });
    if (SESSION) {
        payload.s = SESSION;
    } else {
        payload.init_data = tg.initData;
    }
    return payload;
}

function post(path, params) {
    var payload = auth(params);
    var body = Object.keys(payload).map(function (k) {
        return k + "=" + encodeURIComponent(payload[k]);
    }).join("&");
    return fetch("/telegram/approval/app/" + BOT_ID + path, {
        method: "POST",
        headers: {"Content-Type": "application/x-www-form-urlencoded"},
        body: body
    }).then(function (resp) { return resp.json(); })
    .then(function (res) {
        // Any endpoint may hand back a fresher session.
        if (res && res.session) { SESSION = res.session; }
        return res;
    });
}

function el(tag, cls, html) {
    var e = document.createElement(tag);
    if (cls) { e.className = cls; }
    if (html !== undefined) { e.innerHTML = html; }
    return e;
}

// el() assigns innerHTML, so anything coming from a record
// (product names, units, order refs) has to be escaped or a
// "<" in a catalogue name silently eats the rest of the row.
function esc(value) {
    return String(value === null || value === undefined ? "" : value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/[>]/g, "&gt;")
        .replace(/"/g, "&quot;");
}

function disable(wrap) {
    wrap.querySelectorAll("button").forEach(function (b) {
        b.disabled = true;
    });
}

function notify(msg) {
    if (tg.showAlert) { tg.showAlert(msg); } else { alert(msg); }
}

function act(r, action, extra) {
    var params = {
        approver_id: r.approver_id,
        action: action
    };
    Object.keys(extra).forEach(function (k) {
        params[k] = extra[k];
    });
    post("/act", params).then(function (res) {
        if (!res.ok) { notify(L.failed + " " + (res.error || "")); }
        load();
    });
}

function refuseForm(r, wrap) {
    var f = el("div", "form");
    var sel = el("select", "field");
    sel.appendChild(new Option(L.no_reason, "0"));
    (r.reasons || []).forEach(function (rs) {
        sel.appendChild(new Option(rs.name, rs.id));
    });
    var ta = el("textarea", "field");
    ta.placeholder = L.comment;
    var ok = el("button", "btn danger", esc(L.confirm_refusal));
    ok.onclick = function () {
        disable(wrap);
        act(r, "refuse", {reason_id: sel.value, note: ta.value});
    };
    f.appendChild(el("div", "lbl", esc(L.refusal_reason)));
    f.appendChild(sel);
    f.appendChild(ta);
    f.appendChild(ok);
    return f;
}

function changeForm(r, wrap) {
    var f = el("div", "form");
    var sel = el("select", "field");
    sel.appendChild(new Option(L.field_date, "date"));
    sel.appendChild(new Option(L.field_reason, "reason"));
    var ta = el("textarea", "field");
    ta.placeholder = L.change_hint;
    var ok = el("button", "btn", esc(L.confirm));
    ok.onclick = function () {
        disable(wrap);
        act(r, "change", {field: sel.value, note: ta.value});
    };
    f.appendChild(el("div", "lbl", esc(L.field_to_fix)));
    f.appendChild(sel);
    f.appendChild(ta);
    f.appendChild(ok);
    return f;
}

function actions(r) {
    var wrap = el("div", "actions");
    var bOk = el("button", "btn ok",
        '<i class="fa fa-check"></i> ' + esc(L.approve));
    var bCh = el("button", "btn",
        '<i class="fa fa-pencil"></i> ' + esc(L.changes));
    var bNo = el("button", "btn danger",
        '<i class="fa fa-times"></i> ' + esc(L.refuse));
    var host = el("div", "formhost");
    bOk.onclick = function () { disable(wrap); act(r, "approve", {}); };
    bCh.onclick = function () {
        host.innerHTML = "";
        host.appendChild(changeForm(r, wrap));
    };
    bNo.onclick = function () {
        host.innerHTML = "";
        host.appendChild(refuseForm(r, wrap));
    };
    wrap.appendChild(bOk);
    wrap.appendChild(bCh);
    wrap.appendChild(bNo);
    wrap.appendChild(host);
    return wrap;
}

function buildCard(r) {
    var card = el("div", "card");
    var head = el("div", "folio", esc(r.name));
    if (L.states[r.state]) {
        head.appendChild(el("span", "state-tag", reqState(r.state)));
    }
    card.appendChild(head);
    card.appendChild(el("div", "cat", esc(r.category)));

    card.appendChild(kv(L.requester, r.owner));
    if (r.amount) {
        card.appendChild(kv(L.amount, money(r.currency, r.amount)));
    }
    if (r.quantity) {
        card.appendChild(kv(L.quantity, String(r.quantity)));
    }
    if (r.partner) { card.appendChild(kv(L.vendor, r.partner)); }
    if (r.reference) { card.appendChild(kv(L.reference, r.reference)); }
    if (r.location) { card.appendChild(kv(L.location, r.location)); }
    if (r.journal) { card.appendChild(kv(L.journal, r.journal)); }
    if (r.date) { card.appendChild(kv(L.date, r.date)); }
    if (r.date_start) {
        card.appendChild(kv(L.date_start, r.date_start));
    }
    if (r.date_end) { card.appendChild(kv(L.date_end, r.date_end)); }
    if (r.date_deadline) {
        card.appendChild(kv(L.date_deadline, r.date_deadline));
    }
    if (r.priority && r.priority !== "0") {
        card.appendChild(kv(L.priority,
            L.priorities[r.priority] || r.priority));
    }

    if (r.lines && r.lines.length) {
        card.appendChild(el("div", "section",
            esc(L.products) +
            (r.lines_source ? " · " + esc(r.lines_source) : "")));
        r.lines.forEach(function (l) {
            // The document's own currency when the server
            // sent one; the request's only as a fallback.
            var cur = l.currency || r.currency;
            var total = l.subtotal === undefined
                ? (l.quantity || 0) * (l.price_unit || 0)
                : l.subtotal;
            var qty = (l.quantity || 0) +
                (l.uom ? " " + esc(l.uom) : "");
            card.appendChild(el("div", "line",
                (l.order ? esc(l.order) + " · " : "") +
                esc(l.product || l.description) + " — " +
                qty + " × " +
                money(cur, l.price_unit) + " = " +
                money(cur, total)));
        });
        if (r.lines_more) {
            card.appendChild(el("div", "line",
                esc(L.more_lines.replace(
                    /%\(count\)s/, r.lines_more))));
        }
    }

    if (r.reason) {
        card.appendChild(el("div", "section", esc(L.description)));
        card.appendChild(el("div", "desc", r.reason));
    }

    if (r.approvers && r.approvers.length) {
        card.appendChild(el("div", "section", esc(L.approvers)));
        r.approvers.forEach(function (a) {
            card.appendChild(el("div", "appr",
                (APPR_ICON[a.state] || "") + " " + esc(a.name)));
        });
    }

    if (r.attachments && r.attachments.length) {
        card.appendChild(el("div", "section", esc(L.attachments)));
        r.attachments.forEach(function (a) {
            card.appendChild(attachmentRow(a));
        });
    }

    if (r.can_act) {
        card.appendChild(actions(r));
    } else if (r.approver_state === "approved") {
        card.appendChild(el("div", "badge",
            ICON.check + " " + esc(L.already_approved)));
    } else if (r.approver_state === "refused") {
        card.appendChild(el("div", "badge",
            ICON.times + " " + esc(L.already_refused)));
    } else {
        card.appendChild(el("div", "badge",
            reqState(r.state) || esc(r.state)));
    }
    return card;
}

function render(data) {
    useLabels(data.labels);
    if (!data.ok) {
        listEl.className = "empty";
        listEl.textContent = data.error === "unlinked"
            ? L.unlinked
            : L.session || "⚠️";
        return;
    }
    if (!data.requests.length) {
        listEl.className = "empty";
        listEl.textContent = L.empty;
        return;
    }
    listEl.className = "";
    listEl.innerHTML = "";
    data.requests.forEach(function (r) {
        listEl.appendChild(buildCard(r));
    });
}

function load() {
    post("/pending", {request_id: REQUEST_ID})
        .then(render)
        .catch(function () {
            listEl.className = "empty";
            listEl.textContent = L.network || "⚠️";
        });
}

load();


var BOT_ID = document.body.dataset.botId;
var REQUEST_ID = document.body.dataset.requestId;
var tg = window.Telegram.WebApp;
tg.ready();
tg.expand();
var panel = document.getElementById("panel");
var L = {};

function useLabels(labels) {
    if (!labels) { return; }
    L = labels;
    document.documentElement.lang = L.lang;
    document.title = L.fix_title;
    document.getElementById("heading").textContent = L.fix_title;
}

function el(tag, cls, html) {
    var e = document.createElement(tag);
    if (cls) { e.className = cls; }
    if (html !== undefined) { e.innerHTML = html; }
    return e;
}
// Signed session issued after the server validates initData
// once, so the save call costs no token decrypt.
var SESSION = null;

function auth(params) {
    var payload = {};
    Object.keys(params).forEach(function (k) {
        payload[k] = params[k];
    });
    if (SESSION) {
        payload.s = SESSION;
    } else {
        payload.init_data = tg.initData;
    }
    return payload;
}

function post(path, params) {
    var payload = auth(params);
    var body = Object.keys(payload).map(function (k) {
        return k + "=" + encodeURIComponent(payload[k]);
    }).join("&");
    return fetch("/telegram/approval/app/" + BOT_ID + path, {
        method: "POST",
        headers: {"Content-Type": "application/x-www-form-urlencoded"},
        body: body
    }).then(function (r) { return r.json(); })
    .then(function (res) {
        if (res && res.session) { SESSION = res.session; }
        return res;
    });
}
function notify(msg) {
    if (tg.showAlert) { tg.showAlert(msg); } else { alert(msg); }
}

function esc(value) {
    return String(value === null || value === undefined ? "" : value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/[>]/g, "&gt;")
        .replace(/"/g, "&quot;");
}

function build(res) {
    useLabels(res.labels);
    if (!res.ok) {
        panel.className = "empty";
        panel.textContent = {
            not_owner: L.not_owner,
            unlinked: L.unlinked
        }[res.error] || L.session || "⚠️";
        return;
    }
    panel.className = "";
    panel.innerHTML = "";
    panel.appendChild(el("div", "folio"));
    panel.lastChild.textContent = L.request + " " + res.name;
    if (res.comment) {
        var c = el("div", "comment");
        c.appendChild(el("span", "ct",
            '<i class="fa fa-comment-o"></i> ' + esc(L.to_fix)));
        c.appendChild(document.createTextNode(res.comment));
        panel.appendChild(c);
    }
    var card = el("div", "card");
    var input;
    if (res.field === "date") {
        card.appendChild(el("div", "lbl", esc(L.new_date)));
        input = el("input", "field");
        input.type = "date";
        input.value = res.value;
    } else {
        card.appendChild(el("div", "lbl", esc(L.new_reason)));
        input = el("div", "field editor");
        input.contentEditable = "true";
        input.innerHTML = res.value;
    }
    card.appendChild(input);
    panel.appendChild(card);
    var btn = el("button", "btn",
        '<i class="fa fa-save"></i> ' + esc(L.save_resend));
    btn.onclick = function () {
        btn.disabled = true;
        var newValue = res.field === "date"
            ? input.value : input.innerHTML;
        post("/fix/" + REQUEST_ID + "/save",
            {value: newValue})
            .then(function (r) {
                if (r.ok) {
                    notify(L.fix_sent);
                    tg.close();
                } else {
                    btn.disabled = false;
                    notify(L.failed + " " + (r.error || ""));
                }
            });
    };
    panel.appendChild(btn);
}

post("/fix/" + REQUEST_ID + "/data", {})
    .then(build)
    .catch(function () {
        panel.className = "empty";
        panel.textContent = L.network || "⚠️";
    });
